const templateCategories=['All Templates','Free Templates','Wedding','Boarding Pass','Tickets','Receipt','Newspaper','Korean','Photography','Creative','Favorites','My Templates'];
const previewValues=event=>({'event.name':event?.name||'A Moment to Remember','event.coupleNames':event?.name||'The Happy Couple','event.date':event?.startsAt?new Date(event.startsAt).toLocaleDateString():'Wedding Date','event.venue':event?.venue||'Event Venue','event.startTime':event?.startsAt?new Date(event.startsAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'Event Time','event.logo':'Event Logo','event.reference':event?.id?.slice(0,8).toUpperCase()||'EVENT-001','business.name':'Your Studio','business.logo':'Studio Logo','session.captureDate':'Capture Date','session.captureTime':'Capture Time','session.qrCode':'QR CODE'});
